SELECT l.library_id, l.library_name, (SELECT MAX(da.created_time) FROM bt_dc_document_activity da WHERE da.library_id = l.library_id AND da.status_cd = '00A' AND da.action_type IN ('CREATE', 'EDIT', 'UPLOAD')) AS lastUpdateTime, (SELECT COUNT(*) FROM bt_dc_document WHERE library_id = l.library_id AND status_cd = #{statusCd}) AS documentCount, (SELECT d.updator_id FROM bt_dc_document d WHERE d.library_id = l.library_id AND d.status_cd = #{statusCd} AND d.updated_time = (SELECT MAX(d2.updated_time) FROM bt_dc_document d2 WHERE d2.library_id = l.library_id AND d2.status_cd = #{statusCd}) 1) AS lastUpdaterUserId, (SELECT COUNT(*) FROM bt_dc_document_activity da WHERE da.library_id = l.library_id AND da.user_id = #{userId} AND da.status_cd = '00A') AS accessCount, (SELECT COALESCE(MAX(da.created_time), l.created_time) FROM bt_dc_document_activity da WHERE da.library_id = l.library_id AND da.user_id = #{userId} AND da.status_cd = '00A') AS lastAccessTime, l.color, l.library_icon,l.tenant_id,l.space_id,l.created_time FROM bt_dc_document_library l WHERE l.status_cd = #{statusCd}
AND l.tenant_id = #{tenantId}
AND l.space_id = #{spaceId}
AND EXISTS ( SELECT 1 FROM bt_dc_document_activity da WHERE da.library_id = l.library_id AND da.user_id = #{userId} AND da.status_cd = '00A' ) ORDER BY accessCount desc, lastAccessTime desc 7

SELECT * FROM ( SELECT l.library_id, l.library_name, (SELECT MAX(da.created_time) FROM bt_dc_document_activity da WHERE da.library_id = l.library_id AND da.status_cd = '00A' AND da.action_type IN ('CREATE', 'EDIT', 'UPLOAD')) AS "lastUpdateTime", (SELECT COUNT(*) FROM bt_dc_document WHERE library_id = l.library_id AND status_cd = #{statusCd}) AS "documentCount", (SELECT d.updator_id FROM bt_dc_document d WHERE d.library_id = l.library_id AND d.status_cd = #{statusCd} AND d.updated_time = (SELECT MAX(d2.updated_time) FROM bt_dc_document d2 WHERE d2.library_id = l.library_id AND d2.status_cd = #{statusCd}) AND ROWNUM <= 1) AS "lastUpdaterUserId", (SELECT COUNT(*) FROM bt_dc_document_activity da WHERE da.library_id = l.library_id AND da.user_id = #{userId} AND da.status_cd = '00A') AS "accessCount", (SELECT COALESCE(MAX(da.created_time), l.created_time) FROM bt_dc_document_activity da WHERE da.library_id = l.library_id AND da.user_id = #{userId} AND da.status_cd = '00A') AS "lastAccessTime", l.color, l.library_icon, l.tenant_id, l.space_id, l.created_time FROM bt_dc_document_library l WHERE l.status_cd = #{statusCd}
AND l.tenant_id = #{tenantId}
AND l.space_id = #{spaceId}
AND EXISTS ( SELECT 1 FROM bt_dc_document_activity da WHERE da.library_id = l.library_id AND da.user_id = #{userId} AND da.status_cd = '00A' ) ORDER BY "accessCount" desc, "lastAccessTime" desc ) t WHERE ROWNUM <= 7

SELECT d.document_id, d.document_name, d.content_source, d.document_type, l.tenant_id, l.space_id, CASE WHEN d.document_type = 'FOLDER' THEN 'folder' WHEN d.document_type = 'WORD' THEN 'file-text' WHEN d.document_type = 'EXCEL' THEN 'file-excel' WHEN d.document_type = 'PDF' THEN 'file-pdf' WHEN d.document_type = 'PPT' THEN 'file-powerpoint' WHEN d.document_type = 'TXT' THEN 'file-text' WHEN d.document_type = 'IMAGE' THEN 'file-image' WHEN d.document_type = 'MD' THEN 'file-text' WHEN d.document_type = 'KLB' THEN 'file-image' WHEN d.document_type = 'FILE' THEN 'file' ELSE 'file' END AS "fileIcon", l.library_name AS "libraryPath", l.library_id, d.creator_id AS "creatorUserId", da.created_time AS "lastOpenTime", d.updated_time AS "lastModifiedTime", -- 跨数据库兼容：用 1/0 代替 true/false CASE WHEN f.target_id IS NOT NULL THEN 1 ELSE 0 END AS "isFavorite", CASE WHEN EXISTS ( SELECT 1 FROM bt_dc_document_library lib WHERE lib.library_id = d.library_id AND lib.visibility_scope = 'PRIVATE' AND lib.is_builtin = 'T' AND lib.library_name = '我的文档' AND lib.status_cd = '00A' ) THEN 'T' ELSE 'F' END AS "myDoc" FROM bt_dc_document_activity da JOIN bt_dc_document d ON da.document_id = d.document_id JOIN bt_dc_document_library l ON d.library_id = l.library_id LEFT JOIN bt_dc_user_favorite f ON d.document_id = f.target_id AND f.status_cd = '00A' AND f.target_type = 'DOCUMENT' AND f.user_id = #{queryParams.userId} and f.tenant_id = #{queryParams.tenantId} AND f.status_cd = '00A' WHERE da.user_id = #{queryParams.userId} AND da.status_cd = '00A' AND da.action_type= 'VIEW' AND d.status_cd = '00A' AND l.status_cd = '00A'
AND l.tenant_id = #{queryParams.tenantId} AND da.tenant_id = #{queryParams.tenantId}
AND l.space_id = #{queryParams.spaceId}
AND da.created_time = ( SELECT MAX(da2.created_time) FROM bt_dc_document_activity da2 WHERE da2.document_id = da.document_id AND da2.user_id = #{queryParams.userId} AND da2.status_cd = '00A' AND da2.action_type = 'VIEW' )
AND d.document_type IN ('WORD', 'WORD_ONLINE')
AND d.document_type IN ('EXCEL', 'EXCEL_ONLINE')
AND d.document_type = #{queryParams.fileType}
AND d.creator_id = #{queryParams.userId}
AND d.creator_id != #{queryParams.userId}
ORDER BY d.updated_time ASC
ORDER BY d.updated_time DESC
ORDER BY da.created_time ASC
ORDER BY da.created_time DESC

