SELECT tmp_docs.document_id, tmp_docs.document_name, tmp_docs.document_type, tmp_docs.content_source, tmp_docs.creator_id, tmp_docs.created_time, tmp_docs.updated_time, tmp_docs.library_name, tmp_docs.library_id, tmp_docs.space_id, tmp_docs.tenant_id, tmp_docs.myDoc, tmp_docs.lastModifiedTime FROM ( SELECT d.document_id, d.document_name, d.document_type, d.content_source, d.creator_id, d.created_time, d.updated_time, l.library_name, l.library_id, d.space_id, d.tenant_id, CASE WHEN EXISTS ( SELECT 1 FROM bt_dc_document_library lib WHERE lib.library_id = d.library_id AND lib.visibility_scope = 'PRIVATE' AND lib.is_builtin = 'T' AND lib.library_name = '我的文档' AND lib.status_cd = '00A' ) THEN 'T' ELSE 'F' END AS myDoc, d.updated_time AS lastModifiedTime FROM bt_dc_document d JOIN bt_dc_document_library l ON d.library_id = l.library_id WHERE d.status_cd = '00A' AND d.document_type not in('FOLDER','ROOT') AND l.status_cd = '00A' and d.document_type != 'ROOT' AND d.document_name LIKE
#{queryParams.keyword}
AND d.document_type = #{queryParams.type}
AND d.library_id = #{queryParams.libraryId}
AND d.space_id = #{queryParams.spaceId}
AND d.tenant_id = #{queryParams.tenantId}
ORDER BY d.updated_time DESC ) tmp_docs WHERE 1=1 200

