UPDATE bt_dc_user_homepage_pin p1
SET prev_pin_id = (
  SELECT p2.prev_pin_id
  FROM bt_dc_user_homepage_pin p2
  WHERE p2.tenant_id = #{tenantId}
    AND p2.target_id = #{targetId}
    AND p2.target_type = #{targetType}
    AND p2.status_cd = '00A'
    AND p2.pin_id = p1.prev_pin_id
    AND p2.creator_id = p1.creator_id
 1
),
    updated_time = 
WHERE p1.tenant_id = #{tenantId}
  AND p1.status_cd = '00A'
  AND p1.prev_pin_id IN (
    SELECT pin_id
    FROM bt_dc_user_homepage_pin
    WHERE tenant_id = #{tenantId}
      AND target_id = #{targetId}
      AND target_type = #{targetType}
      AND status_cd = '00A'
  )

UPDATE bt_dc_user_homepage_pin p1
JOIN (
  SELECT p1_inner.pin_id,
         p2.prev_pin_id AS new_prev_pin_id
  FROM bt_dc_user_homepage_pin p1_inner
  JOIN bt_dc_user_homepage_pin p2
    ON p2.pin_id = p1_inner.prev_pin_id
    AND p2.creator_id = p1_inner.creator_id
  WHERE p1_inner.tenant_id = #{tenantId}
    AND p1_inner.status_cd = '00A'
    AND p2.tenant_id = #{tenantId}
    AND p2.target_id = #{targetId}
    AND p2.target_type = #{targetType}
    AND p2.status_cd = '00A'
) AS derived ON p1.pin_id = derived.pin_id
SET p1.prev_pin_id = derived.new_prev_pin_id,
    p1.updated_time = 
WHERE p1.tenant_id = #{tenantId}
  AND p1.status_cd = '00A'

MERGE INTO bt_dc_user_homepage_pin p1
USING (
  SELECT p1_inner.pin_id,
         p2.prev_pin_id AS new_prev_pin_id
  FROM bt_dc_user_homepage_pin p1_inner
  JOIN bt_dc_user_homepage_pin p2
    ON p2.pin_id = p1_inner.prev_pin_id
    AND p2.creator_id = p1_inner.creator_id
  WHERE p1_inner.tenant_id = #{tenantId}
    AND p1_inner.status_cd = '00A'
    AND p2.tenant_id = #{tenantId}
    AND p2.target_id = #{targetId}
    AND p2.target_type = #{targetType}
    AND p2.status_cd = '00A'
) derived ON (p1.pin_id = derived.pin_id)
WHEN MATCHED THEN
  UPDATE SET p1.prev_pin_id = derived.new_prev_pin_id,
             p1.updated_time = 
  WHERE p1.tenant_id = #{tenantId}
    AND p1.status_cd = '00A'

