SELECT da.document_id, da.user_id, da.action_type, da.created_time FROM bt_dc_document_activity da INNER JOIN ( SELECT document_id, MAX(created_time) as max_time FROM bt_dc_document_activity WHERE document_id IN
#{documentId}
AND action_type = 'VIEW' AND status_cd = '00A' GROUP BY document_id ) latest ON da.document_id = latest.document_id AND da.created_time = latest.max_time WHERE da.action_type = 'VIEW' AND da.status_cd = '00A'

SELECT da.document_id, da.user_id, da.action_type, da.created_time FROM bt_dc_document_activity da INNER JOIN ( SELECT document_id, MAX(created_time) as max_time FROM bt_dc_document_activity WHERE document_id IN
#{documentId}
AND action_type = 'EDIT' AND status_cd = '00A' GROUP BY document_id ) latest ON da.document_id = latest.document_id AND da.created_time = latest.max_time WHERE da.action_type = 'EDIT' AND da.status_cd = '00A'

SELECT DISTINCT tmp_docs.document_id, tmp_docs.document_name, tmp_docs.document_type, tmp_docs.content_source, tmp_docs.creator_id, tmp_docs.created_time, tmp_docs.updated_time, tmp_docs.library_name, tmp_docs.library_id, tmp_docs.space_id, tmp_docs.tenant_id, tmp_docs.myDoc, tmp_docs.lastModifiedTime FROM ( SELECT DISTINCT d.document_id, d.document_name, d.document_type, d.content_source, d.creator_id, d.created_time, d.updated_time, l.library_name, l.library_id, d.space_id, d.tenant_id, CASE WHEN EXISTS ( SELECT 1 FROM bt_dc_document_library lib WHERE lib.library_id = d.library_id AND lib.visibility_scope = 'PRIVATE' AND lib.is_builtin = 'T' AND lib.library_name = '我的文档' AND lib.status_cd = '00A' ) THEN 'T' ELSE 'F' END AS myDoc, COALESCE(da.created_time, d.updated_time) AS lastModifiedTime FROM bt_dc_document d JOIN bt_dc_document_library l ON d.library_id = l.library_id LEFT JOIN ( SELECT document_id, MAX(created_time) as created_time FROM bt_dc_document_activity WHERE user_id = #{userId} AND action_type in ('VIEW', 'EDIT') AND status_cd = '00A' GROUP BY document_id ) da ON d.document_id = da.document_id WHERE d.status_cd = '00A' AND d.document_type not in('FOLDER','ROOT') AND l.status_cd = '00A' AND ( da.document_id IS NOT NULL OR d.creator_id = #{userId} )
AND d.document_type = #{type}
AND d.library_id = #{libraryId}
AND d.space_id = #{spaceId}
AND d.tenant_id = #{tenantId}
ORDER BY lastModifiedTime DESC ) tmp_docs WHERE 1=1 200
